description:
Develop a binary-to-BCD converter that transforms a 14-bit binary input into a 16-bit binary-coded decimal (BCD) output. This module sequentially processes each bit of the binary input, applying the double-dabble algorithm to adjust BCD digits that exceed the value of 5 by adding a binary 3. The result is a 16-bit output representing the equivalent BCD value of the input binary number.
module top_module(
input [13:0] bin,
output reg [15:0] bcd 
);

code:
module top_module(
input [13:0] bin,
output reg [15:0] bcd 
);integer i;

always @(bin) begin
bcd=0;             
for (i=0;i<14;i=i+1) begin                    
if (bcd[3:0] >= 5) bcd[3:0] = bcd[3:0] + 3;        
    if (bcd[7:4] >= 5) bcd[7:4] = bcd[7:4] + 3;
    if (bcd[11:8] >= 5) bcd[11:8] = bcd[11:8] + 3;
    if (bcd[15:12] >= 5) bcd[15:12] = bcd[15:12] + 3;


    bcd = {bcd[14:0],bin[13-i]};                
end
end
endmodule

