module jk_flip_flop(clk, rst, j, k, q);

    input clk;
    input rst;
    input j;
    input k;
    output q;
    reg q;

    always @(posedge clk or posedge rst)
    begin
        if (rst)
            q <= 1'b0;
        else
        begin
            case ({j, k})
                2'b00: q <= q;
                2'b01: q <= 1'b0;
                2'b10: q <= 1'b1;
                2'b11: q <= ~q;
            endcase
        end
    end

endmodule

