    if (binary[3] == 1) begin
        abs_val = ~binary + 1;
    end else begin
        abs_val = binary;
    end
end

// Final output module
always @(*) begin
    if (areset) begin
        final_output = 4'b0000;
    end else begin
        final_output = abs_val;
    end
end

endmodule

